insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Hospital nearby", "B": "Railroad crossing", "C": "School crossing", "D": "Emergency vehicles"}$q$::jsonb, $q$D$q$, $q$This warning sign indicates a fire station or emergency vehicles may be entering or crossing the roadway ahead. Be alert for emergency vehicles.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w11-8.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Hospital cercano", "B": "Cruce de ferrocarril", "C": "Cruce escolar", "D": "Vehículos de emergencia"}$q$::jsonb, $q$Esta señal de advertencia indica una estación de bomberos o que vehículos de emergencia pueden entrar o cruzar la vía más adelante. Manténgase alerta.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Watch for responders", "B": "Yield to all traffic", "C": "Stop at the sign", "D": "Turn on headlights"}$q$::jsonb, $q$A$q$, $q$This sign warns that emergency vehicles may be entering or crossing ahead. Slow down if needed and watch for emergency vehicles.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w11-8.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Atento a emergencias", "B": "Ceda a todo el tráfico", "C": "Pare en la señal", "D": "Encienda los faros"}$q$::jsonb, $q$Esta señal advierte que vehículos de emergencia pueden entrar o cruzar más adelante. Reduzca la velocidad si es necesario y esté atento.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what should you do in the left lane?$q$, $q${"A": "Go straight only", "B": "Merge right", "C": "Turn left only", "D": "Yield to oncoming"}$q$::jsonb, $q$C$q$, $q$This advance lane control sign tells you the left lane is for left turns only. The right lane may turn left or continue straight.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-8.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer en el carril izquierdo?$q$, $q${"A": "Solo seguir recto", "B": "Pasar a la derecha", "C": "Solo girar a la izq.", "D": "Ceder al de enfrente"}$q$::jsonb, $q$Esta señal de control de carriles indica que el carril izquierdo es solo para dar vuelta a la izquierda. El carril derecho puede doblar a la izquierda o seguir recto.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what should you do?$q$, $q${"A": "Use headlights now", "B": "Merge into traffic", "C": "Prepare to stop", "D": "Slow down on wet road"}$q$::jsonb, $q$D$q$, $q$This sign warns that the road may be slippery when wet. Reduce speed and use extra caution in rainy or wet conditions.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w8-5.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer?$q$, $q${"A": "Encender los faros", "B": "Incorporarse", "C": "Prepararse a parar", "D": "Reducir la velocidad"}$q$::jsonb, $q$Esta señal advierte que la carretera puede estar resbaladiza cuando está mojada. Reduzca la velocidad y maneje con más precaución en condiciones húmedas o de lluvia.$q$);
